import * as React from "react";

export function MaskedHeading({ text = "The Future of Interfaces", className = "" }: { text?: string; className?: string }): React.JSX.Element {
  const [x, setX] = React.useState(0);
  React.useEffect(() => {
    const id = setInterval(() => setX(p => (p + 0.4) % 200), 16);
    return () => clearInterval(id);
  }, []);
  return (
    <div className={`relative overflow-hidden select-none ${className}`} style={{ WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent", backgroundClip: "text", background: `linear-gradient(90deg, #1a1a2e ${x - 20}%, #ba442c ${x}%, #f59e0b ${x + 15}%, #38bdf8 ${x + 30}%, #1a1a2e ${x + 50}%)`, backgroundSize: "200% 100%", display: "inline-block" }}>
      <span className="font-display font-black text-4xl tracking-tight">{text}</span>
    </div>
  );
}

import * as React from "react";
import { MaskedHeading } from "./masked-heading";

export default function MaskedHeadingDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <MaskedHeading
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
